src={(0,0),(0,2),(1,1),(2,1)}; out={(0,2),(1,0),(1,1),(2,2)}
# all transforms normalized mapping to out plus arbitrary translations; determine src-point mapping to target output (1,0)
for refl in [False,True]:
 for k in range(4):
  pts=[]; maps={}
  for p in src:
   x,y=p
   if refl:y=-y
   for _ in range(k): x,y=y,-x
   maps[p]=(x,y); pts.append((x,y))
  a=min(x for x,y in pts); b=min(y for x,y in pts)
  norm={p:(q[0]-a,q[1]-b) for p,q in maps.items()}
  if set(norm.values())==out:
   inv={v:k for k,v in norm.items()}
   print(refl,k,inv.get((1,0)))
